+
+// BindPort is a one-time composition step; there is no default/no-op provider.
+func (s *ProtectedObjects) BindPort(port ProtectedObjectPort) error {
+	if port == nil || s.port != nil {
+		return ErrStorageScope
+	}
+	s.port = port
+	return nil
