+
+func (s *ProtectedObjects) CheckWorkspace(_ context.Context, w uuid.UUID) error {
+	if w != s.scope.WorkspaceID || !time.Now().UTC().Before(s.scope.ExpiresAt) {
+		return ErrStorageDenied
+	}
+	return nil
