+			return err
+		}
+		v, err := s.gate(ctx, tx, version, purpose == "CREATE")
+		if err != nil {
+			return err
+		}
+		if purpose != "CREATE" && (v.ChecksumValue != hash || v.ByteSize == nil || *v.ByteSize != size) {
+			return ErrStorageContract
+		}
+		if err = s.sources(ctx, tx, v); err != nil {
