+		if err = rows.Scan(&id); err != nil {
+			rows.Close()
+			return nil, err
+		}
+		ids = append(ids, id)
+	}
+	err = rows.Err()
+	rows.Close()
+	if err != nil {
+		return nil, err
+	}
+	if len(ids) != 1 {
+		return nil, ErrStorageScope
+	}
+	return s.ReadVersion(ctx, ids[0])
