+	if err != nil {
+		return nil, err
+	}
+	h := sha256.Sum256(data)
+	if int64(len(data)) != i.ByteSize || hex.EncodeToString(h[:]) != i.SHA256 {
+		return nil, ErrStorageContract
+	}
