+		}
+		return appendOccupancyFacts(ctx, tx, StorageCallStartedEvent, "LIFECYCLE_STORAGE_CALL", id, s.caller(), rev, time.Now().UTC(), map[string]any{"operation": "PROTECTED_" + method, "protected_object_intent_id": i.ID})
+	})
+	return id, err
