+// and inventory constraints are exercised in CI without a MinIO service.
+type protectedControlledPort struct {
+	s            *lc.ProtectedObjects
+	mu           sync.Mutex
+	objects      map[string][]byte
+	lostResponse bool
+	denied       bool
+	calls        int
+}
